changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Allemagne – Secrétaires d''État fédéraux', 'Secrétaires d''État parlementaires, ministres d''État et secrétaires d''État fonctionnaires des ministères fédéraux, et anciens ministres sortis depuis moins de 12 mois (catégorie DE-a)', 'de_pep_federal_secretaries', 'PEP', 'https://www.bundestag.de/dokumente/parlamentsarchiv/datenhandbuch/06/kapitel-06-475940', 'de-pep-federal-secretaries', 'D:/test parser 2/plugins/swiftcheck-aml-de-pep-federal-secretaries-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'OFFICIAL_GAZETTE', NULL, '{"chapterUrl": "https://www.bundestag.de/dokumente/parlamentsarchiv/datenhandbuch/06/kapitel-06-475940", "term": "21", "monthsAfterEnd": "12"}', 168, 12, 'Citer la source (Deutscher Bundestag, Datenhandbuch)', 'Deutscher Bundestag, Datenhandbuch, chapitre 6.3, www.bundestag.de', 'Lit le tableau « Namentliche Aufstellung der Minister und Staatssekretäre » (PDF du chapitre 6.3) : trois colonnes découpées par position. Le PDF est un instantané mis à jour par le service du Bundestag ; l''adresse du PDF est découverte sur la page du chapitre. Le message d''exécution donne la date du document.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Secrétaires d''État parlementaires, ministres d''État et secrétaires d''État fonctionnaires de la 21e législature, avec dates d''arrivée et de départ, y compris les sortis depuis moins de 12 mois.', 'Instantané du Datenhandbuch (daté dans le message d''exécution) : un changement postérieur n''est pas vu. Les secrétaires d''État de la Chancellerie et des ministères sont lus ; pas les Länder.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Secrétaire d''État parlementaire ou secrétaire d''État%' AND p.dataset_name = 'de_pep_federal_secretaries';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Anciens ministres fédéraux de la 21e législature dont le départ date de moins de 12 mois (remaniement du 29/07/2026).', 'Anciens membres des gouvernements des Länder non couverts ; instantané du Datenhandbuch.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'DE-a' AND f.label LIKE 'Ancien membre du gouvernement fédéral%' AND p.dataset_name = 'de_pep_federal_secretaries';
